/* ---------- Grid ---------- */
.grid {
  position: relative;
  width: 100%;
}

.grid__item {
  position: absolute;
  top: 0;
  left: 0;
  border-radius: 8px;
  outline: none;
  transition:
    transform 0.2s ease,
    width 0.2s ease,
    height 0.2s ease;
}

.grid__item:focus-visible {
  box-shadow: 0 0 0 2px var(--g-color-line-focus);
}

.grid__item_active {
  z-index: 5;
  transition: none;
}

.grid__item_active .widget {
  box-shadow: 0 8px 24px var(--g-color-sfx-shadow);
}

.grid__placeholder {
  position: absolute;
  top: 0;
  left: 0;
  border: 1px dashed var(--g-color-line-brand);
  border-radius: 8px;
  background: var(--g-color-base-selection);
  pointer-events: none;
  transition:
    transform 0.15s ease,
    width 0.15s ease,
    height 0.15s ease;
}

.grid__resize {
  position: absolute;
  right: 0;
  bottom: 0;
  width: 20px;
  height: 20px;
  cursor: nwse-resize;
  touch-action: none;
  z-index: 2;
}

.grid__resize::after {
  content: '';
  position: absolute;
  right: 5px;
  bottom: 5px;
  width: 8px;
  height: 8px;
  border-right: 2px solid var(--g-color-text-hint);
  border-bottom: 2px solid var(--g-color-text-hint);
  border-bottom-right-radius: 2px;
  opacity: 0.6;
}

.grid__item:hover .grid__resize::after,
.grid__item:focus-within .grid__resize::after {
  opacity: 1;
}

